function empty(ic,title,text){return `<div class="empty"><div class="emptyicon">${icon(ic)}</div><h3>${title}</h3><p>${text}</p></div>`}
function emailModal(id){try{const e=generateEmail(repo,id),equipment=repo.load('equipment').find(x=>x.requestId===id);if(equipment?.type==='Carreta com Lock'){const carrier=equipment.supplierName?`${equipment.supplierName}${equipment.supplierCnpj?' · CNPJ: '+equipment.supplierCnpj:''}`:repo.load('suppliers').find(x=>x.id===equipment.supplierId)?.name||'Não informada';e.body=e.body.replace(`Transportadora da carreta: ${carrier}`,match=>`${match}\nValor da carreta: ${money(equipment.carrierValue)}`)};modal.innerHTML=`<h2>Prévia da cotação</h2><div class="emailtools"><label>Assunto<input id="emailSubject" value="${esc(e.subject)}"></label></div><label>Corpo do e-mail<textarea id="emailBody" style="min-height:330px">${esc(e.body)}</textarea></label><div class="formfooter"><button data-close>Fechar</button><button data-generate>Gerar novamente</button><button class="primary" data-copy>${icon('copy')} Copiar e-mail</button></div>`;modal.showModal();modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-generate]').onclick=()=>emailModal(id);modal.querySelector('[data-copy]').onclick=async()=>{await navigator.clipboard.writeText(`ASSUNTO: ${modal.querySelector('#emailSubject').value}\n\n${modal.querySelector('#emailBody').value}`);toast('E-mail copiado.')}}catch(x){fail(x)}}
