 const supplier=(id,name,cnpj)=>name?`${name}${cnpj?' · CNPJ '+cnpj:''}`:repo.load('suppliers').find(x=>x.id===id)?.name||'',rows=repo.load('requests').map(r=>{const c=repo.load('companies').find(x=>x.id===r.companyId),e=repo.load('equipment').find(x=>x.requestId===r.id)||{},q=repo.load('quotes').find(x=>x.requestId===r.id&&x.status==='Aprovada')||{},o=repo.load('operations').find(x=>x.requestId===r.id),f=repo.load('finance').find(x=>x.operationId===o?.id),bill=repo.load('billing').find(x=>x.requestId===r.id)||{},items=repo.load('items').filter(x=>x.requestId===r.id).map(i=>`${i.description}; ${i.material}; qtd ${i.quantity}; ${i.length}x${i.width}x${i.height}m; ${i.weight}kg; ${i.volumes} vol.`).join(' | '),a=e.originCrane||{},b=e.destinationCrane||{};return [r.number,r.createdAt,r.createdByName,r.status,c?.name,r.cnpj,r.pv,r.pc,r.reason,r.collection.address,r.collection.cep,r.collection.link,r.delivery.address,r.delivery.cep,r.delivery.link,r.needsSpecialEquipment?'Sim':'Não',e.type,e.movement,e.capacity,e.boom,supplier(e.supplierId,e.supplierName,e.supplierCnpj),e.carrierValue,e.containerId,e.containerType,e.containerCount,a.enabled?'Sim':'Não',supplier(a.supplierId,a.supplierName,a.supplierCnpj),a.capacity,a.movement,a.date,a.notes,b.enabled?'Sim':'Não',supplier(b.supplierId,b.supplierName,b.supplierCnpj),b.capacity,b.movement,b.date,b.notes,items,supplierName(q),q.value,q.status,o?.status,f?.status,bill.supplierName,bill.debtorCompanyName,bill.dueDate,bill.invoice,bill.documentNumber,bill.approver,bill.total,bill.status,(bill.files||[]).map(x=>x.name).join(' | ')]});
 const csv='\ufeff'+[headers,...rows].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`gestao-fretes-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('Exportação gerada.')
