function invoiceEntry(){invoicePage('logistica')}
function invoiceInbox(){invoicePage('financeiro')}
function invoicePage(view){const entry=view==='logistica',title=entry?'Lançar faturas':'Faturas Localiza';shell(`<div class="pagehead"><div><div class="eyebrow">${entry?'Logística':'Financeiro'}</div><h1>${title}</h1><p>${entry?'Registre a fatura da Localiza, anexe os documentos e encaminhe ao Financeiro.':'Acompanhe as faturas da Localiza recebidas da Logística, confira os documentos e registre pagamentos ou pendências.'}</p></div></div><iframe title="${title}" src="/faturas?view=${view}&embedded=1" style="display:block;width:100%;height:78vh;min-height:550px;border:1px solid #d9dde3;border-radius:12px;background:white"></iframe>`)}
function render(){seed();if(!state.user)return loginView();if((state.page!=='operations'&&!can(state.user,state.page))||(state.page==='operations'&&!can(state.user,'operations')&&!can(state.user,'finance'))){state.page=rolePermissions(state.user.role)[0]||'dashboard'}try{({dashboard,requests,equipment,locks,quotes,operations,deliveries,history,suppliers,users,invoiceEntry,invoiceInbox}[state.page]||dashboard)()}catch(x){fail(x);state.page='dashboard';dashboard()}}
async function initialize(){try{const me=await fetch('/api/fretes/me',{cache:'no-store'});if(me.status===401){loginView();return}if(me.status===403){app.innerHTML=`<div class="loginform"><h2>Acesso ainda não autorizado</h2><p>Peça ao administrador para cadastrar o e-mail desta conta ChatGPT em Usuários e permissões.</p><a href="/signout-with-chatgpt?return_to=/index.html">Trocar de conta</a></div>`;return}if(!me.ok)throw Error('Falha ao validar o acesso.');state.user=await me.json();seed();await repo.enableRemote(state.user);render();window.addEventListener('freight-sync-error',e=>toast(e.detail));setInterval(async()=>{try{if(repo.pending.size)return;const r=await fetch('/api/fretes/data',{cache:'no-store'});if(r.ok){repo.mergeRemote((await r.json()).collections||{},state.user.role);if(!modal.open)render()}}catch{}},20000)}catch(error){app.innerHTML=`<div class="loginform"><h2>Não foi possível carregar os fretes</h2><p>${esc(error.message)}</p><button class="primary" onclick="location.reload()">Tentar novamente</button></div>`}}
initialize();
